-- Hedgestone Global Bank - complete database setup
--
-- Generated by scripts/build-setup-sql.js from supabase/migrations/. Do not
-- edit by hand: change a migration and run `npm run build:sql`.
--
-- Paste this whole file into Supabase, SQL Editor, New query, and run it.
-- Safe to run more than once, and to run again after an update.
--
-- Afterwards, to open the /admin desk: create your login under
-- Authentication, Users (tick Auto Confirm User), then run
-- supabase/grant-admin.sql with your address on its marked line.

-- Includes: 0001_init.sql, 0002_email.sql, 0003_bank.sql, 0004_bank_sms.sql, 0005_bank_invest.sql


-- ==========================================================================
-- 0001_init.sql
-- ==========================================================================

-- Merkel Constructions backend schema.
--
-- Safe to run more than once: every statement is guarded, so re-running the
-- file after an edit updates what changed rather than erroring half way.
--
-- Five areas: the contact inbox (enquiries), job applications, a two-table
-- live chat, the admin list, and the studio's own contact details. Everything is behind row level security. The only writes the
-- browser makes directly are a visitor creating their own chat session and
-- posting into it. Contact submissions never touch the database from the
-- browser: they go through POST /api/contact, which holds the service role key
-- and also sends the notification email.

-- ---------------------------------------------------------------------------
-- Admins
-- ---------------------------------------------------------------------------

create table if not exists public.admins (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  email      text,
  created_at timestamptz not null default now()
);

alter table public.admins enable row level security;

-- SECURITY DEFINER so the check itself is not subject to RLS on `admins`,
-- which would otherwise recurse when used inside the policies below.
create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.admins where user_id = auth.uid());
$$;

drop policy if exists "admins read own row" on public.admins;
create policy "admins read own row"
  on public.admins for select
  to authenticated
  using (user_id = auth.uid());

-- ---------------------------------------------------------------------------
-- Shared triage status
-- ---------------------------------------------------------------------------

do $$
begin
  if not exists (select 1 from pg_type where typname = 'item_status') then
    create type public.item_status as enum ('new', 'in_progress', 'closed');
  end if;
end
$$;

-- ---------------------------------------------------------------------------
-- Contact enquiries
-- ---------------------------------------------------------------------------

create table if not exists public.enquiries (
  id         uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  name       text not null,
  email      text not null,
  company    text,
  service    text,
  message    text not null,
  ip         text,
  status     public.item_status not null default 'new',
  notes      text
);

-- Upgrade path from the earlier flat schema, which called the timestamp
-- `received_at` and had no triage columns.
do $$
begin
  if exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'enquiries'
      and column_name = 'received_at'
  ) and not exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'enquiries'
      and column_name = 'created_at'
  ) then
    alter table public.enquiries rename column received_at to created_at;
  end if;
end
$$;

alter table public.enquiries add column if not exists status public.item_status not null default 'new';
alter table public.enquiries add column if not exists notes text;
alter table public.enquiries add column if not exists ip text;

create index if not exists enquiries_created_at_idx
  on public.enquiries (created_at desc);

alter table public.enquiries enable row level security;

-- No anon policy at all: inserts arrive via the API's service role, which
-- bypasses RLS. Only signed-in admins can read or triage.
drop policy if exists "admins read enquiries" on public.enquiries;
create policy "admins read enquiries"
  on public.enquiries for select to authenticated using (public.is_admin());

drop policy if exists "admins update enquiries" on public.enquiries;
create policy "admins update enquiries"
  on public.enquiries for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- ---------------------------------------------------------------------------
-- Site settings
-- ---------------------------------------------------------------------------

-- The studio's contact details, so they can be changed from the dashboard and
-- take effect on the next page load rather than the next deploy. One row.
create table if not exists public.site_settings (
  id         text primary key default 'default',
  updated_at timestamptz not null default now(),
  address    text,
  email      text,
  phone      text,
  hours      text
);

insert into public.site_settings (id) values ('default')
    on conflict (id) do nothing;

alter table public.site_settings enable row level security;

-- Read goes through GET /api/site using the service role, which is why there
-- is no anon policy here even though the values are public. Only admins write.
drop policy if exists "admins read site settings" on public.site_settings;
create policy "admins read site settings"
  on public.site_settings for select to authenticated using (public.is_admin());

drop policy if exists "admins update site settings" on public.site_settings;
create policy "admins update site settings"
  on public.site_settings for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- ---------------------------------------------------------------------------
-- Job applications
-- ---------------------------------------------------------------------------

create table if not exists public.applications (
  id         uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  name       text not null,
  email      text not null,
  phone      text,
  role_id    text,
  role_title text,
  portfolio  text,
  experience text,
  message    text not null,
  ip         text,
  status     public.item_status not null default 'new',
  notes      text
);

create index if not exists applications_created_at_idx
  on public.applications (created_at desc);

alter table public.applications enable row level security;

-- Same rule as enquiries: no anon policy at all. Applications arrive through
-- POST /api/applications using the service role, and only admins can read them.
drop policy if exists "admins read applications" on public.applications;
create policy "admins read applications"
  on public.applications for select to authenticated using (public.is_admin());

drop policy if exists "admins update applications" on public.applications;
create policy "admins update applications"
  on public.applications for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- ---------------------------------------------------------------------------
-- Live chat
-- ---------------------------------------------------------------------------

-- `visitor_id` is the anonymous auth uid the widget signs in with, so a
-- visitor can read their own thread and nobody else's without us inventing a
-- token scheme of our own. Requires anonymous sign-ins to be enabled under
-- Authentication, Providers, Anonymous.
create table if not exists public.chat_sessions (
  id              uuid primary key default gen_random_uuid(),
  created_at      timestamptz not null default now(),
  visitor_id      uuid not null default auth.uid(),
  visitor_name    text,
  visitor_email   text,
  last_message_at timestamptz not null default now(),
  status          public.item_status not null default 'new'
);

-- Set once a member of the studio answers, so the canned responder steps
-- aside and the visitor is not talked over. It cannot be read off `status`:
-- the trigger below returns a thread to 'new' every time the visitor speaks.
alter table public.chat_sessions
  add column if not exists handled_by_agent boolean not null default false;

create index if not exists chat_sessions_last_message_idx
  on public.chat_sessions (last_message_at desc);

create table if not exists public.chat_messages (
  id         uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  session_id uuid not null references public.chat_sessions (id) on delete cascade,
  sender     text not null check (sender in ('visitor', 'agent')),
  body       text not null check (length(body) between 1 and 4000)
);

create index if not exists chat_messages_session_idx
  on public.chat_messages (session_id, created_at);

alter table public.chat_sessions enable row level security;
alter table public.chat_messages enable row level security;

drop policy if exists "visitor creates own session" on public.chat_sessions;
create policy "visitor creates own session"
  on public.chat_sessions for insert to authenticated
  with check (visitor_id = auth.uid());

drop policy if exists "visitor or admin reads session" on public.chat_sessions;
create policy "visitor or admin reads session"
  on public.chat_sessions for select to authenticated
  using (visitor_id = auth.uid() or public.is_admin());

drop policy if exists "visitor names own session" on public.chat_sessions;
create policy "visitor names own session"
  on public.chat_sessions for update to authenticated
  using (visitor_id = auth.uid()) with check (visitor_id = auth.uid());

drop policy if exists "admin triages session" on public.chat_sessions;
create policy "admin triages session"
  on public.chat_sessions for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

drop policy if exists "visitor posts to own session" on public.chat_messages;
create policy "visitor posts to own session"
  on public.chat_messages for insert to authenticated
  with check (
    sender = 'visitor'
    and exists (
      select 1 from public.chat_sessions s
      where s.id = session_id and s.visitor_id = auth.uid()
    )
  );

drop policy if exists "admin posts as agent" on public.chat_messages;
create policy "admin posts as agent"
  on public.chat_messages for insert to authenticated
  with check (sender = 'agent' and public.is_admin());

drop policy if exists "visitor or admin reads messages" on public.chat_messages;
create policy "visitor or admin reads messages"
  on public.chat_messages for select to authenticated
  using (
    public.is_admin()
    or exists (
      select 1 from public.chat_sessions s
      where s.id = session_id and s.visitor_id = auth.uid()
    )
  );

-- Keep the inbox ordered by activity without the client having to maintain it.
create or replace function public.touch_chat_session()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.chat_sessions
     set last_message_at = new.created_at,
         -- A visitor speaking puts the conversation back on the waiting pile,
         -- including one already answered or closed, so a follow-up cannot go
         -- unnoticed. An agent reply leaves the status alone; the dashboard
         -- sets it to in_progress itself.
         status = case when new.sender = 'visitor' then 'new' else status end
   where id = new.session_id;
  return new;
end;
$$;

drop trigger if exists chat_messages_touch_session on public.chat_messages;
create trigger chat_messages_touch_session
  after insert on public.chat_messages
  for each row execute function public.touch_chat_session();

-- Realtime: both sides of the conversation stream over these two tables.
-- Realtime honours the policies above, so a visitor only ever receives rows
-- from their own session.
do $$
begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and tablename = 'chat_messages'
  ) then
    alter publication supabase_realtime add table public.chat_messages;
  end if;

  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and tablename = 'chat_sessions'
  ) then
    alter publication supabase_realtime add table public.chat_sessions;
  end if;

  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and tablename = 'enquiries'
  ) then
    alter publication supabase_realtime add table public.enquiries;
  end if;

  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and tablename = 'applications'
  ) then
    alter publication supabase_realtime add table public.applications;
  end if;
end
$$;


-- ==========================================================================
-- 0002_email.sql
-- ==========================================================================

-- Email inbox for the admin dashboard.
--
-- Mail addressed to the studio mailbox arrives through Resend Inbound, which
-- holds the MX records and posts an `email.received` webhook to
-- /api/inbound/resend. Replies are sent from the dashboard through Resend and
-- recorded here alongside the inbound side, so a thread reads as one
-- conversation.
--
-- Optional: the site works fine without any of this. Skip it if you are not
-- receiving mail.
--
-- Safe to run more than once. Requires 0001_init.sql (item_status, is_admin).

-- ---------------------------------------------------------------------------
-- Threads
-- ---------------------------------------------------------------------------

create table if not exists public.email_threads (
  id                uuid primary key default gen_random_uuid(),
  created_at        timestamptz not null default now(),
  last_message_at   timestamptz not null default now(),
  subject           text not null default '(no subject)',
  -- The person on the other end. Threads are per correspondent, not per
  -- mailbox, so a reply lands back on the conversation it belongs to.
  participant_email text not null,
  participant_name  text,
  status            public.item_status not null default 'new'
);

create index if not exists email_threads_activity_idx
  on public.email_threads (last_message_at desc);

-- Used to re-find a thread when a reply carries no In-Reply-To header, which
-- some clients omit. Subject is stored already stripped of Re:/Fwd:.
create index if not exists email_threads_match_idx
  on public.email_threads (lower(participant_email), lower(subject));

-- ---------------------------------------------------------------------------
-- Messages
-- ---------------------------------------------------------------------------

create table if not exists public.email_messages (
  id              uuid primary key default gen_random_uuid(),
  created_at      timestamptz not null default now(),
  thread_id       uuid not null references public.email_threads (id) on delete cascade,
  direction       text not null check (direction in ('inbound', 'outbound')),
  from_email      text not null,
  from_name       text,
  to_email        text not null,
  subject         text,
  body_text       text,
  body_html       text,
  -- RFC 5322 Message-ID, and the header that points at its parent. Kept so
  -- replies thread correctly in the recipient's mail client, not just ours.
  message_id      text,
  in_reply_to     text,
  has_attachments boolean not null default false
);

create index if not exists email_messages_thread_idx
  on public.email_messages (thread_id, created_at);

-- Inbound mail can be delivered more than once; the Message-ID makes the
-- insert idempotent so a retry does not duplicate the conversation.
create unique index if not exists email_messages_message_id_key
  on public.email_messages (message_id) where message_id is not null;

-- ---------------------------------------------------------------------------
-- Access
-- ---------------------------------------------------------------------------

alter table public.email_threads enable row level security;
alter table public.email_messages enable row level security;

-- Staff only, both directions. Everything written here arrives via the server
-- routes using the service role, which bypasses RLS, so there is deliberately
-- no insert policy for the browser at all.
drop policy if exists "admins read email threads" on public.email_threads;
create policy "admins read email threads"
  on public.email_threads for select to authenticated using (public.is_admin());

drop policy if exists "admins update email threads" on public.email_threads;
create policy "admins update email threads"
  on public.email_threads for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

drop policy if exists "admins read email messages" on public.email_messages;
create policy "admins read email messages"
  on public.email_messages for select to authenticated using (public.is_admin());

-- ---------------------------------------------------------------------------
-- Keep the inbox ordered, and flag threads the correspondent spoke on last
-- ---------------------------------------------------------------------------

create or replace function public.touch_email_thread()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.email_threads
     set last_message_at = new.created_at,
         -- Inbound mail always returns a thread to the waiting pile, however
         -- it was filed before. Our own replies leave the status alone; the
         -- dashboard sets it to in_progress itself.
         status = case when new.direction = 'inbound' then 'new' else status end
   where id = new.thread_id;
  return new;
end;
$$;

drop trigger if exists email_messages_touch_thread on public.email_messages;
create trigger email_messages_touch_thread
  after insert on public.email_messages
  for each row execute function public.touch_email_thread();

-- Realtime, so a message arriving lands in an open dashboard without a reload.
do $$
begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and tablename = 'email_messages'
  ) then
    alter publication supabase_realtime add table public.email_messages;
  end if;

  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and tablename = 'email_threads'
  ) then
    alter publication supabase_realtime add table public.email_threads;
  end if;
end
$$;


-- ==========================================================================
-- 0003_bank.sql
-- ==========================================================================

-- ============================================================================
-- Hedgestone Global Bank - schema for the banking application.
--
-- Apply after 0001_init.sql and 0002_email.sql. Every table is written to by
-- the server with the service-role key, which bypasses row level security, so
-- RLS is enabled and left with no permissive policy: nothing reaches these
-- tables from a browser holding only the anon key. Authorisation is decided in
-- the application, where the session lives.
--
-- Money is integer cents throughout. Timestamps are ISO-8601 in UTC.
-- ============================================================================

-- ------------------------------------------------------------------ users --
create table if not exists public.bank_users (
  id uuid primary key,
  created_at timestamptz not null default now(),
  updated_at timestamptz,
  customer_number text unique,
  role text not null default 'customer',              -- customer | admin
  status text not null default 'active',              -- active | pending | suspended | closed
  email text not null unique,
  email_verified boolean not null default false,
  password_hash text not null,
  must_change_password boolean not null default false,
  password_changed_at timestamptz,

  first_name text,
  middle_name text,
  last_name text,
  preferred_name text,
  date_of_birth text,
  ssn_encrypted text,                                 -- AES-256-GCM, never plaintext
  ssn_last4 text,
  tax_id_type text default 'SSN',
  citizenship text,
  id_type text,
  id_number text,                                     -- encrypted
  id_state text,
  id_expires text,

  phone text,
  mobile text,
  address_line1 text,
  address_line2 text,
  city text,
  state text,
  postal_code text,
  country text,
  mailing_same_as_home boolean default true,

  employment_status text,
  employer text,
  occupation text,
  annual_income bigint default 0,
  source_of_funds text,

  photo_url text,
  photo_document_id uuid,

  kyc_status text default 'pending',                  -- pending | review | verified | rejected
  kyc_notes text,
  kyc_reviewed_at timestamptz,
  risk_rating text default 'standard',
  tier text default 'Standard',
  relationship_manager text,

  two_factor_enabled boolean default true,
  two_factor_method text default 'email',
  transfer_pin_hash text,
  security_question text,
  security_answer_hash text,

  alert_prefs jsonb,
  alert_threshold bigint default 50000,
  low_balance_threshold bigint default 10000,
  paperless boolean default true,
  language text default 'en-US',
  timezone text default 'America/New_York',

  failed_logins integer default 0,
  locked_until timestamptz,
  last_login_at timestamptz,
  last_login_ip text,
  login_count integer default 0,
  opened_by uuid,
  notes text
);
create index if not exists bank_users_email_idx on public.bank_users (email);
create index if not exists bank_users_status_idx on public.bank_users (status);

-- --------------------------------------------------------------- accounts --
create table if not exists public.bank_accounts (
  id uuid primary key,
  created_at timestamptz not null default now(),
  user_id uuid not null references public.bank_users (id) on delete cascade,
  type text not null,                                 -- checking | savings | money_market | cd | credit | loan | mortgage | ira
  product_id text,
  name text,
  nickname text,
  account_number text not null unique,
  routing_number text not null,
  swift text,
  currency text not null default 'USD',
  status text not null default 'active',              -- active | frozen | restricted | dormant | closed
  balance bigint not null default 0,
  opening_balance bigint not null default 0,
  hold_amount bigint not null default 0,
  available_balance bigint not null default 0,
  credit_limit bigint default 0,
  overdraft_limit bigint default 0,
  overdraft_protection boolean default true,
  interest_rate numeric default 0,
  apy numeric default 0,
  apr numeric default 0,
  minimum_balance bigint default 0,
  monthly_fee bigint default 0,
  term_months integer default 0,
  maturity_date text,
  statement_day integer default 1,
  opened_at timestamptz,
  closed_at timestamptz,
  last_activity_at timestamptz,
  is_primary boolean default false,
  notes text
);
create index if not exists bank_accounts_user_idx on public.bank_accounts (user_id);

-- ----------------------------------------------------------- transactions --
create table if not exists public.bank_transactions (
  id uuid primary key,
  created_at timestamptz not null default now(),
  posted_at timestamptz,
  date timestamptz not null,                          -- value date, which is what a statement orders by
  user_id uuid not null references public.bank_users (id) on delete cascade,
  account_id uuid not null references public.bank_accounts (id) on delete cascade,
  direction text not null,                            -- credit | debit
  amount bigint not null check (amount > 0),
  currency text not null default 'USD',
  description text not null,
  merchant text,
  category text,
  method text,                                        -- ach | wire_domestic | card | check | ...
  status text not null default 'posted',              -- posted | pending | hold | failed | reversed | scheduled
  balance_after bigint,
  reference text,
  trace_number text,
  check_number text,
  memo text,
  location text,
  counterparty jsonb,
  transfer_id uuid,
  reversed_by uuid,
  created_by text,                                    -- customer | admin | system
  created_by_id uuid,
  admin_note text,
  meta jsonb
);
create index if not exists bank_transactions_account_idx on public.bank_transactions (account_id, date desc);
create index if not exists bank_transactions_user_idx on public.bank_transactions (user_id, date desc);
create index if not exists bank_transactions_status_idx on public.bank_transactions (status);

-- --------------------------------------------------------------- transfers --
create table if not exists public.bank_transfers (
  id uuid primary key,
  created_at timestamptz not null default now(),
  user_id uuid not null references public.bank_users (id) on delete cascade,
  type text not null,                                 -- internal | ach | wire_domestic | wire_international | instant | bill_pay
  method text,
  from_account_id uuid references public.bank_accounts (id) on delete set null,
  to_account_id uuid references public.bank_accounts (id) on delete set null,
  beneficiary_id uuid,
  payee_id uuid,
  amount bigint not null,
  fee bigint not null default 0,
  total bigint not null,
  currency text default 'USD',
  memo text,
  purpose text,
  status text not null,                               -- draft | pending_verification | pending_review | scheduled | processing | completed | rejected | cancelled | failed
  scheduled_for timestamptz,
  recurrence text default 'none',
  recurrence_end timestamptz,
  parent_transfer_id uuid,
  confirmation text,
  trace_number text,
  imad text,
  omad text,
  requires_otp boolean default false,
  otp_verified boolean default false,
  pin_verified boolean default false,
  reason_code text,
  reason_note text,
  reviewed_by uuid,
  reviewed_at timestamptz,
  completed_at timestamptz,
  debit_transaction_id uuid,
  credit_transaction_id uuid,
  ip text,
  snapshot jsonb                                      -- the recipient as they were when it was sent
);
create index if not exists bank_transfers_user_idx on public.bank_transfers (user_id, created_at desc);
create index if not exists bank_transfers_status_idx on public.bank_transfers (status);

-- ----------------------------------------------------------- beneficiaries --
create table if not exists public.bank_beneficiaries (
  id uuid primary key,
  created_at timestamptz not null default now(),
  user_id uuid not null references public.bank_users (id) on delete cascade,
  nickname text,
  name text not null,
  bank_name text,
  account_number text not null,
  routing_number text,
  swift text,
  account_type text,
  type text not null,                                 -- domestic_ach | domestic_wire | international_wire
  country text,
  address text,
  bank_address text,
  relationship text,
  memo text,
  status text default 'pending',                      -- pending | verified | blocked
  verified_at timestamptz,
  last_used_at timestamptz
);
create index if not exists bank_beneficiaries_user_idx on public.bank_beneficiaries (user_id);

-- -------------------------------------------------------------------- cards --
create table if not exists public.bank_cards (
  id uuid primary key,
  created_at timestamptz not null default now(),
  user_id uuid not null references public.bank_users (id) on delete cascade,
  account_id uuid not null references public.bank_accounts (id) on delete cascade,
  brand text,
  kind text,                                          -- debit | credit
  number_encrypted text,                              -- the PAN never leaves the server in the clear
  last4 text,
  bin text,
  name_on_card text,
  exp_month integer,
  exp_year integer,
  cvv_encrypted text,
  status text default 'active',                       -- active | frozen | lost | stolen | expired | cancelled
  design text,
  daily_purchase_limit bigint default 750000,
  daily_atm_limit bigint default 100000,
  contactless boolean default true,
  international_allowed boolean default false,
  online_allowed boolean default true,
  pin_set boolean default true,
  activated_at timestamptz,
  replaced_card_id uuid,
  notes text
);
create index if not exists bank_cards_user_idx on public.bank_cards (user_id);

-- ------------------------------------------------------------------- payees --
create table if not exists public.bank_payees (
  id uuid primary key,
  created_at timestamptz not null default now(),
  user_id uuid not null references public.bank_users (id) on delete cascade,
  name text not null,
  category text,
  account_number text,
  amount bigint default 0,
  due_day integer,
  autopay boolean default false,
  phone text,
  address text,
  status text default 'active',
  last_paid_at timestamptz
);
create index if not exists bank_payees_user_idx on public.bank_payees (user_id);

-- ----------------------------------------------------------------- deposits --
create table if not exists public.bank_deposits (
  id uuid primary key,
  created_at timestamptz not null default now(),
  user_id uuid not null references public.bank_users (id) on delete cascade,
  account_id uuid not null references public.bank_accounts (id) on delete cascade,
  amount bigint not null,
  check_number text,
  front_document_id uuid,
  back_document_id uuid,
  transaction_id uuid,
  status text default 'review',                       -- review | accepted | rejected
  hold_until timestamptz,
  available_now bigint default 0,
  reason_note text,
  reviewed_by uuid,
  reviewed_at timestamptz,
  reference text
);

-- ---------------------------------------------------------------- documents --
create table if not exists public.bank_documents (
  id uuid primary key,
  created_at timestamptz not null default now(),
  user_id uuid not null references public.bank_users (id) on delete cascade,
  kind text not null,                                 -- avatar | id_front | id_back | ssn_card | proof_address | check_front | ...
  filename text,
  mime text,
  size integer,
  data text,                                          -- data: URL; swap for object storage at volume
  status text default 'received',
  uploaded_by text,
  uploaded_by_id uuid,
  note text,
  reviewed_at timestamptz
);
create index if not exists bank_documents_user_idx on public.bank_documents (user_id);

-- ----------------------------------------------------------------- activity --
create table if not exists public.bank_activity (
  id uuid primary key,
  created_at timestamptz not null default now(),
  user_id uuid,
  actor_id uuid,
  actor_email text,
  actor_role text,
  action text not null,
  category text,                                      -- security | money | account | admin
  detail text,
  severity text default 'info',
  channel text default 'web',
  ip text,
  user_agent text,
  device text,
  meta jsonb
);
create index if not exists bank_activity_user_idx on public.bank_activity (user_id, created_at desc);
create index if not exists bank_activity_created_idx on public.bank_activity (created_at desc);

-- ------------------------------------------------------------------- alerts --
create table if not exists public.bank_alerts (
  id uuid primary key,
  created_at timestamptz not null default now(),
  user_id uuid not null references public.bank_users (id) on delete cascade,
  type text,
  channel text default 'email',
  subject text,
  preview text,
  body_text text,
  body_html text,
  severity text default 'info',
  status text default 'queued',                       -- queued | sent | failed | not_configured
  provider_id text,
  error text,
  sent_at timestamptz,
  read_at timestamptz,
  meta jsonb
);
create index if not exists bank_alerts_user_idx on public.bank_alerts (user_id, created_at desc);

-- ----------------------------------------------------------------- messages --
create table if not exists public.bank_messages (
  id uuid primary key,
  created_at timestamptz not null default now(),
  thread_id uuid not null,
  user_id uuid not null references public.bank_users (id) on delete cascade,
  from_side text not null,                            -- customer | bank
  author_name text,
  subject text,
  body text,
  read_at timestamptz,
  attachments jsonb
);
create index if not exists bank_messages_thread_idx on public.bank_messages (thread_id, created_at);

-- ----------------------------------------------------------------- disputes --
create table if not exists public.bank_disputes (
  id uuid primary key,
  created_at timestamptz not null default now(),
  user_id uuid not null references public.bank_users (id) on delete cascade,
  transaction_id uuid,
  account_id uuid,
  amount bigint,
  reason text,
  detail text,
  status text default 'open',                         -- open | provisional_credit | resolved_credit | resolved_declined
  reference text,
  provisional_credit boolean default false,
  resolution text,
  resolved_at timestamptz,
  handled_by uuid
);

-- ----------------------------------------------------------------- sessions --
create table if not exists public.bank_sessions (
  id uuid primary key,
  created_at timestamptz not null default now(),
  user_id uuid not null references public.bank_users (id) on delete cascade,
  token_hash text not null unique,                    -- SHA-256 of the cookie value, never the value
  csrf text,
  expires_at timestamptz,
  last_seen_at timestamptz,
  ip text,
  user_agent text,
  device text,
  device_kind text,
  remember boolean default false,
  revoked_at timestamptz
);
create index if not exists bank_sessions_user_idx on public.bank_sessions (user_id);
create index if not exists bank_sessions_token_idx on public.bank_sessions (token_hash);

-- --------------------------------------------------------------------- otps --
create table if not exists public.bank_otps (
  id uuid primary key,
  created_at timestamptz not null default now(),
  user_id uuid not null references public.bank_users (id) on delete cascade,
  purpose text not null,                              -- login | reset | transfer:<id>
  code_hash text not null,
  expires_at timestamptz,
  attempts integer default 0,
  used_at timestamptz,
  meta jsonb
);
create index if not exists bank_otps_user_idx on public.bank_otps (user_id, purpose);

-- ----------------------------------------------------------------- settings --
create table if not exists public.bank_settings (
  id text primary key,
  values jsonb not null,
  updated_at timestamptz
);

-- --------------------------------------------------------------------- RLS --
-- Every table below is server-only. RLS on with no policy means the anon key
-- reads and writes nothing; the service-role key the server holds bypasses it.
do $$
declare t text;
begin
  foreach t in array array[
    'bank_users', 'bank_accounts', 'bank_transactions', 'bank_transfers',
    'bank_beneficiaries', 'bank_cards', 'bank_payees', 'bank_deposits',
    'bank_documents', 'bank_activity', 'bank_alerts', 'bank_messages',
    'bank_disputes', 'bank_sessions', 'bank_otps', 'bank_settings'
  ]
  loop
    execute format('alter table public.%I enable row level security', t);
  end loop;
end $$;


-- ==========================================================================
-- 0004_bank_sms.sql
-- ==========================================================================

-- Text message delivery, recorded beside the email it went out with.
--
-- An alert has always been one row with one status, because there was one
-- channel. Adding Pingram gave it a second, and a second can fail on its own:
-- an SMS provider being down must not mark a delivered email as failed, and
-- the other way round. So the text gets its own status and its own error, and
-- `channel` says which were attempted.
--
-- Safe to run on a database that already has these columns, and safe to run
-- more than once.

alter table public.bank_alerts add column if not exists sms_status text;
alter table public.bank_alerts add column if not exists sms_error text;

comment on column public.bank_alerts.sms_status is
  'sent | failed | not_configured. Null when no text was attempted.';
comment on column public.bank_alerts.sms_error is
  'What the SMS provider said when it refused. Null on success.';


-- ==========================================================================
-- 0005_bank_invest.sql
-- ==========================================================================

-- 0005_bank_invest.sql
--
-- Converting a balance into listed assets: what each customer holds, every
-- trade that changed it, and the last price seen for each asset.
--
-- Run after 0003_bank.sql. Guarded, so running it twice is safe.
--
-- Units are numeric(30, 8): a holding is divided to a millionth of a share or a
-- satoshi of Bitcoin, and the server does its arithmetic on exact integers, so
-- these columns must never be float. Cash is bigint cents, as everywhere else.

-- --------------------------------------------------------------- holdings --
create table if not exists public.bank_holdings (
  id uuid primary key,
  created_at timestamptz not null default now(),
  updated_at timestamptz,
  user_id uuid not null references public.bank_users (id) on delete cascade,
  symbol text not null,                               -- SPY | QQQ | AAPL | ... | BTC | XAU
  units numeric(30, 8) not null default 0,
  cost_basis bigint not null default 0,               -- cents paid for the units still held
  unique (user_id, symbol)
);
create index if not exists bank_holdings_user_idx on public.bank_holdings (user_id);

-- ----------------------------------------------------------------- trades --
create table if not exists public.bank_trades (
  id uuid primary key,
  created_at timestamptz not null default now(),
  user_id uuid not null references public.bank_users (id) on delete cascade,
  account_id uuid references public.bank_accounts (id) on delete set null,
  symbol text not null,
  side text not null,                                 -- buy | sell
  units numeric(30, 8) not null,
  price bigint not null,                              -- cents per unit, at the moment of the trade
  amount bigint not null,                             -- cents debited (buy) or credited (sell)
  realized_gain bigint,                               -- sells only: proceeds less the cost of the units sold
  transaction_id uuid,
  reference text,
  quote_source text,                                  -- which price provider answered
  quote_as_of timestamptz
);
create index if not exists bank_trades_user_idx on public.bank_trades (user_id, created_at desc);

-- ---------------------------------------------------------- market quotes --
-- One row per asset, overwritten on every refresh. Lets a cold serverless
-- instance show the last known price, with its age, while it fetches a new one.
create table if not exists public.bank_market_quotes (
  id text primary key,                                -- the symbol
  symbol text not null,
  price numeric(20, 6) not null,
  previous_close numeric(20, 6),
  change numeric(20, 6),
  change_pct numeric(10, 4),
  source text,
  as_of timestamptz,
  fetched_at timestamptz not null default now()
);

-- Server-only, like every bank table: RLS on with no policy.
alter table public.bank_holdings enable row level security;
alter table public.bank_trades enable row level security;
alter table public.bank_market_quotes enable row level security;

